<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,defineAsyncComponent} from 'vue';
import {ArrowLeft,Download,Eye,EyeOff,ChevronRight,ChevronLeft,Play,Pause,Box,Check,Cable,Printer,BookOpen,ShoppingBag,ShieldCheck} from '@lucide/vue';
import StudioViewport from './StudioViewport.vue';
import CarWireDiagram from './CarWireDiagram.vue';
import CarWireDetail from './CarWireDetail.vue';
import BuildPrintPlan from './BuildPrintPlan.vue';
import BuildAppearance from './BuildAppearance.vue';
const DrivingSandbox=defineAsyncComponent(()=>import('./DrivingSandbox.vue'));
import type {BuildAppearancePlan} from './BuildAppearance.vue';
import type {PrintPlan} from './BuildPrintPlan.vue';
import type {ToyPart,CadPart,Selection,Projection,ElectricalConnection,AssemblyFrame,WireDisplayReport} from '../viewport/types';
import {assemblyFrame} from '../viewport/assembly-playback.mjs';
import {withDisplayRoutes} from '../viewport/display-routes.mjs';
import {hasWireRoute} from '../viewport/interaction.mjs';
type Step={id:string;title:string;partIds:string[];requires:string[];text:string;checks:string[];tools:string};
type PrintPart={id:string;name:string;file:string;sizeMm:number[];orientation:string;solidEquivalentPlaGrams:number};
type Purchase={name:string;qty:number;spec:string;url?:string;budgetCny:number};
type Build={title:string;appearance?:BuildAppearancePlan;printPlan?:PrintPlan;dimensionsMm?:number[];coverPartIds?:string[];diagramLabels?:Record<string,{title:string;sub:string}>;parts:ToyPart[];cadParts:CadPart[];printParts:PrintPart[];assembly:Step[];connections:ElectricalConnection[];wireDisplay?:WireDisplayReport;bom:Purchase[];checks:{interferenceConflicts:unknown[]};engineering?:{summary:string[]};};
const build=ref<Build>(),error=ref(''),tab=ref('model'),selected=ref<string[]>([]),active=ref<string|null>(null),hidden=ref<string[]>([]),projection=ref<Projection>('perspective'),wire=ref<string|null>(null),stepIndex=ref(0),progress=ref(1),playing=ref(false),search=ref(''),printer=ref(''),completed=ref<string[]>([]);
const buildId=new URLSearchParams(location.search).get('build')==='echo-f1-cn-v2'?'echo-f1-cn-v2':'echo-f1-v1';
const base='/api/authored-builds/'+buildId;
const drivingWheels=buildId==='echo-f1-cn-v2'?['L','R'].flatMap(side=>[
  {id:'rear_'+side,partIds:['rear_tire_'+side,'rear_hub_'+side],radiusMm:21,driven:true},
  {id:'front_'+side,partIds:['front_wheel_'+side,'tire_front_'+side+'_0','tire_front_'+side+'_1'],radiusMm:23.4,driven:false}
]):[];
const checklistKey=buildId+'-checklist';
const coverIds=computed(()=>build.value?.coverPartIds||['body_shell','canopy']);
const wiringMode=ref<'diagram'|'3d'>('diagram'),wireFilter=ref('all');
const coverOpen=ref(true);
const wireKinds=[{id:'all',label:'全部'},{id:'power',label:'电源'},{id:'ground',label:'地线'},{id:'signal',label:'信号'},{id:'motor',label:'电机'}];
const filteredWires=computed(()=>build.value?.connections?.filter(c=>wireFilter.value==='all'||c.kind===wireFilter.value)||[]);
const currentWire=computed(()=>filteredWires.value.find(c=>c.id===wire.value));
const wireIndex=computed(()=>filteredWires.value.findIndex(c=>c.id===wire.value));
const displayConnections=computed(()=>build.value?withDisplayRoutes(build.value.parts,build.value.cadParts,build.value.connections,build.value.wireDisplay):[]);
const viewportConnections=computed(()=>tab.value==='wiring'?displayConnections.value.filter(c=>wireFilter.value==='all'||c.kind===wireFilter.value):displayConnections.value);
const currentDisplayWire=computed(()=>displayConnections.value.find(c=>c.id===wire.value));
const routeReady=computed(()=>!!currentDisplayWire.value&&hasWireRoute(currentDisplayWire.value));
const forcedHidden=computed(()=>tab.value==='wiring'&&coverOpen.value?coverIds.value:[]);
const viewportHidden=computed(()=>[...new Set([...hidden.value,...forcedHidden.value])]);
function applyVisibility(ids:string[]){
  if(!ids.length){hidden.value=[];if(tab.value==='wiring')coverOpen.value=false;return;}
  hidden.value=[...hidden.value.filter(id=>forcedHidden.value.includes(id)),...ids.filter(id=>!forcedHidden.value.includes(id))];
}
function toggleCover(){coverOpen.value=!coverOpen.value;hidden.value=hidden.value.filter(id=>!coverIds.value.includes(id));}
const savedView=new URLSearchParams(location.search).get('view');
if(savedView&&['model','assemble','wiring','print','parts','checks','simulate'].includes(savedView))tab.value=savedView;
if(new URLSearchParams(location.search).get('wire-view')==='3d')wiringMode.value='3d';
const url=(file:string)=>base+'/files/'+file;
const tabs=[{id:'model',label:'设计总览',icon:Box},{id:'simulate',label:'行驶仿真',icon:Play},{id:'assemble',label:'跟着装配',icon:BookOpen},{id:'wiring',label:'电气接线',icon:Cable},{id:'print',label:'打印文件',icon:Printer},{id:'parts',label:'采购清单',icon:ShoppingBag},{id:'checks',label:'检查记录',icon:ShieldCheck}];
const current=computed(()=>build.value?.parts.find(p=>p.id===active.value));
const shownParts=computed(()=>build.value?.parts.filter(p=>p.name.toLowerCase().includes(search.value.toLowerCase()))||[]);
const step=computed(()=>build.value?.assembly?.[stepIndex.value]);
const frame=computed<AssemblyFrame|null>(()=>tab.value==='assemble'&&build.value&&step.value?assemblyFrame(build.value.assembly,build.value.parts,step.value.id,progress.value):null);
const budget=computed(()=>build.value?.bom.reduce((sum,p)=>sum+p.qty*p.budgetCny,0)||0);
const onSelect=(s:Selection)=>{selected.value=s.ids;active.value=s.activeId;};
const toggle=(id:string)=>{hidden.value=hidden.value.includes(id)?hidden.value.filter(x=>x!==id):[...hidden.value,id];};
function selectPart(p:ToyPart,event:MouseEvent){const ids=event.shiftKey?(selected.value.includes(p.id)?selected.value.filter(x=>x!==p.id):[...selected.value,p.id]):[p.id];onSelect({ids,activeId:ids.includes(p.id)?p.id:ids.at(-1)||null});}
let raf=0,start=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function pause(){cancelAnimationFrame(raf);playing.value=false;}
function tick(now:number){progress.value=Math.min(1,(now-start)/2400);if(progress.value<1)raf=requestAnimationFrame(tick);else pause();}
function play(){pause();if(reduced.matches){progress.value=1;return;}progress.value=0;start=performance.now();playing.value=true;raf=requestAnimationFrame(tick);}
function chooseStep(index:number){pause();stepIndex.value=index;progress.value=1;hidden.value=[];if(step.value){selected.value=step.value.partIds;active.value=selected.value[0]||null;}}
function mark(key:string){completed.value=completed.value.includes(key)?completed.value.filter(x=>x!==key):[...completed.value,key];localStorage.setItem(checklistKey,JSON.stringify(completed.value));}
function chooseWire(id:string|null){wire.value=id;const c=build.value?.connections.find(w=>w.id===id);if(c){selected.value=[c.from.partId,c.to.partId];active.value=c.from.partId;hidden.value=hidden.value.filter(x=>!selected.value.includes(x));}}
function filterWires(kind:string){wireFilter.value=kind;if(!filteredWires.value.some(c=>c.id===wire.value))chooseWire(filteredWires.value[0]?.id||null);}
function moveWire(delta:number){const c=filteredWires.value[wireIndex.value+delta];if(c)chooseWire(c.id);}
function changeTab(id:string){pause();tab.value=id;progress.value=1;const address=new URL(location.href);address.searchParams.set('view',id);history.replaceState(null,'',address);if(id==='wiring'&&!wire.value)chooseWire(filteredWires.value[0]?.id||null);}
onMounted(async()=>{try{const r=await fetch(base);if(!r.ok)throw Error('制作包尚未生成，请先运行 CAD 生成器。');build.value=await r.json();if(tab.value==='wiring')chooseWire(filteredWires.value[0]?.id||null);try{const saved=JSON.parse(localStorage.getItem(checklistKey)||'[]');if(Array.isArray(saved))completed.value=saved.filter(x=>typeof x==='string');}catch{/* invalid local checklist is ignored */}}catch(e){error.value=String(e);}});
onBeforeUnmount(pause);
</script>

<template>
  <div class="echo-app">
    <header class="echo-header"><a href="/" class="echo-home"><ArrowLeft :size="15"/> M4KE <span> / BUILD EDITION</span></a><div class="echo-title"><i/> ECHO F1 <span>{{buildId==='echo-f1-cn-v2'?'大陆易装版 · V2':'声控方程式 · V1'}}</span></div><a class="echo-download" :href="url('ECHO-F1-build-package.zip')"><Download :size="16"/> 下载完整制作包</a></header>
    <div v-if="error" class="echo-error" role="alert">{{error}}</div>
    <template v-if="build">
      <nav class="echo-tabs" aria-label="制作阶段"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" @click="changeTab(t.id)"><component :is="t.icon" :size="16"/>{{t.label}}</button><span class="echo-prototype">成人监督原型 · 尚待实物测试</span></nav>
      <main class="echo-layout" :class="{'echo-simulation-layout':tab==='simulate'}">
        <div class="echo-central" :class="{'echo-wiring-central':tab==='wiring'}">
          <DrivingSandbox v-if="tab==='simulate'" :parts="build.parts" :cad-parts="build.cadParts" front-direction="-x" :wheels="drivingWheels" />
          <div v-if="tab==='wiring'" class="echo-wiring-toolbar"><div role="group" aria-label="接线显示方式"><button :aria-pressed="wiringMode==='diagram'" @click="wiringMode='diagram'"><Cable :size="15"/>清晰接线图</button><button :aria-pressed="wiringMode==='3d'" @click="wiringMode='3d'"><Box :size="15"/>3D 定位</button></div><button v-if="wiringMode==='3d'" class="echo-cover-toggle" :aria-pressed="coverOpen" @click="toggleCover"><EyeOff v-if="coverOpen" :size="15"/><Eye v-else :size="15"/>{{coverOpen?'合上外壳':'开壳查看'}}</button><span>{{wiringMode==='diagram'?'先看接口，再看安装位置':coverOpen?'已移开外壳 · 线路正常遮挡':'外壳已合上 · 内部线路会被遮挡'}}</span></div>
          <div v-if="['model','assemble','wiring'].includes(tab)" v-show="tab!=='wiring'||wiringMode==='3d'" class="echo-model">
            <StudioViewport :parts="build.parts" :cad-parts="build.cadParts" :selected-ids="selected" :active-id="active" :hidden-ids="viewportHidden" :connections="viewportConnections" :selected-connection="wire" :projection="projection" :view-mode="tab==='wiring'?'wiring':'model'" :assembly-playback="frame" @select="onSelect" @visibility="applyVisibility" @projection="projection=$event" @select-connection="chooseWire">
              <template #tutorial><div v-if="tab==='assemble'&&step" class="echo-playback"><span>STEP {{String(stepIndex+1).padStart(2,'0')}} / {{build.assembly.length}}</span><strong>{{step.title}}</strong><div><button :disabled="stepIndex===0" aria-label="上一步" @click="chooseStep(stepIndex-1)"><ChevronLeft :size="18"/></button><button :aria-label="playing?'暂停动画':'播放装配动画'" @click="playing?pause():play()"><Pause v-if="playing" :size="18"/><Play v-else :size="18"/></button><input aria-label="装配进度" type="range" min="0" max="1" step="0.01" v-model.number="progress" @input="pause"/><button :disabled="stepIndex===build.assembly.length-1" aria-label="下一步" @click="chooseStep(stepIndex+1)"><ChevronRight :size="18"/></button></div><small>示意移动，不是装配路径仿真；勾选仅记录你的实际检查。</small></div></template>
            </StudioViewport>
            <div v-if="tab==='model'" class="echo-caption"><span>{{build.appearance?'EMBER × WHITE.':'DESIGNED TO BE MADE.'}}</span><h1>让声音，<br/>变成前进的力量。</h1><p>{{build.appearance?build.appearance.title:'红黑分件'}} · 可拆车壳 · 真实尺寸 CAD</p></div>
          </div>
          <CarWireDiagram v-if="tab==='wiring'&&wiringMode==='diagram'" :labels="build.diagramLabels" :parts="build.parts" :connections="filteredWires" :selected-id="wire" @select="chooseWire"/>
          <section v-if="tab==='print'" class="echo-content">
            <BuildPrintPlan v-if="build.printPlan" :plan="build.printPlan" :appearance="build.appearance" :base="base" :build-id="buildId" @assemble="changeTab('assemble');chooseStep(0)"/>
            <div v-else class="echo-section-head"><span>01 / FABRICATE</span><h1>从这一个试片开始。</h1><p>旧版没有多盘工程，以下保留单件备用文件；不要把装配 STEP 整块打印。</p><a class="echo-download" :href="url('print/00_fit_coupon.stl')"><Download :size="16"/> 下载公差试片</a></div>
            <details class="echo-stl-backup" :open="!build.printPlan"><summary>高级备用：单件 STL、重打某个零件（新手请用上方整套 3MF）</summary>
              <label v-if="!build.printPlan" class="echo-printer">选择你的打印机 <select v-model="printer"><option value="">请选择，不预设机型</option><option>Bambu Lab H2C</option><option>Bambu Lab X1 / P1 / A1</option><option>Bambu Lab A1 mini</option><option>其他 FDM 打印机</option></select></label>
              <p v-if="printer==='Bambu Lab A1 mini' && build.printParts.some(p=>p.sizeMm[0]>170||p.sizeMm[1]>170)" class="echo-warning">A1 mini 热床不适合本版长件；不要缩小模型。</p>
              <p class="echo-muted">单位毫米、100% 比例。只在需要单件补打时使用。此页面不连接或自动启动打印机。</p>
              <div class="echo-print-grid"><article v-for="p in build.printParts" :key="p.id"><Printer :size="20"/><h3>{{p.name}}</h3><code>{{p.sizeMm.join(' × ')}} mm</code><p>{{p.orientation}}</p><a :href="url(p.file)"><Download :size="14"/> STL</a></article></div>
            </details>
          </section>
          <section v-if="tab==='parts'" class="echo-content"><div class="echo-section-head"><span>02 / SOURCE</span><h1>每一个零件，都有位置。</h1><p>型号与接口不能随意替换。下表金额是采购预算分配，不是实时成交价；总额目标不超过 ¥600，运费和工具另核对。</p><strong class="echo-budget">¥{{budget}} <small>预算分配合计</small></strong></div><table><thead><tr><th>零件</th><th>数量</th><th>接口 / 型号</th><th>预算单价</th></tr></thead><tbody><tr v-for="p in build.bom" :key="p.name"><td><a v-if="p.url" :href="p.url" target="_blank" rel="noopener noreferrer">{{p.name}} ↗</a><span v-else>{{p.name}}</span></td><td>{{p.qty}}</td><td>{{p.spec}}</td><td>¥{{p.budgetCny}}</td></tr></tbody></table><a :href="url('BOM.csv')">下载采购清单 CSV</a></section>
          <section v-if="tab==='checks'" class="echo-content"><div class="echo-section-head"><span>03 / EVIDENCE</span><h1>能检查的先检查。<br/>没做的，不冒充通过。</h1></div><div class="echo-check-card"><Check :size="24"/><div><h3>实体 CAD 与导出网格</h3><p>每件原生 BRep、STL 封闭性、体积一致性和 STEP 重新导入均由生成器检查。下载与视口使用一致的网格来源。</p></div></div><div class="echo-check-card"><ShieldCheck :size="24"/><div><h3>零件间干涉 · {{build.checks.interferenceConflicts.length===0?'未检测到未解释的体积相交':build.checks.interferenceConflicts.length+' 项待处理'}}</h3><p>不等于实际孔配合、走线空间或打印公差全部通过。</p></div></div><p v-for="line in build.engineering?.summary" :key="line">{{line}}</p><div class="echo-warning">仍需实测：尺寸公差、声音门槛、电机自噪声、启动电流、温升、直行偏差、速度与停车距离。不得直接用于儿童无人监督玩耍。</div><div class="echo-links"><a :href="url('checks/geometry.json')" target="_blank">CAD 检查记录</a><a :href="url('checks/engineering.json')" target="_blank">计算与假设</a><a :href="url('checks/firmware-tests.txt')" target="_blank">固件逻辑测试</a></div></section>
        </div>
        <aside v-if="tab!=='simulate'" class="echo-aside">
          <BuildAppearance v-if="tab==='model'&&build.appearance" :plan="build.appearance" :base="base" compact/>
          <template v-if="tab==='assemble'&&step"><div class="echo-aside-heading">装配顺序 <span>{{stepIndex+1}}/{{build.assembly.length}}</span></div><div class="echo-step-list"><button v-for="(s,i) in build.assembly" :key="s.id" :class="{active:i===stepIndex}" @click="chooseStep(i)"><span>{{String(i+1).padStart(2,'0')}}</span>{{s.title}}</button></div><section class="echo-instructions"><h2>{{step.title}}</h2><p>{{step.text}}</p><small>工具 / 耗材：{{step.tools}}</small><label v-for="(c,i) in step.checks" :key="step.id+i"><input type="checkbox" :checked="completed.includes(step.id+'-'+i)" @change="mark(step.id+'-'+i)"/>{{c}}</label></section></template>
          <template v-else-if="tab==='wiring'">
            <div class="echo-aside-heading">接线助手 <span>{{filteredWires.length}} / {{build.connections.length}} 条</span></div>
            <CarWireDetail v-if="currentWire" :connection="currentWire" :parts="build.parts" :index="wireIndex" :total="filteredWires.length" @previous="moveWire(-1)" @next="moveWire(1)"/>
            <p v-if="wiringMode==='3d'" class="echo-routing-note" role="status" :data-route-ready="routeReady">{{routeReady?'已对当前 CAD 避碰。端点为元件表面附近的示意接口，并非真实焊脚；接线仍按右侧端子名与实物丝印。':'当前线路缺少有效的 3D 避碰路径，不画穿模替代线；请使用清晰接线图。'}}</p>
            <div class="echo-wire-filters" role="group" aria-label="线路分类"><button v-for="k in wireKinds" :key="k.id" :aria-pressed="wireFilter===k.id" @click="filterWires(k.id)">{{k.label}}</button></div>
            <div class="echo-wire-list"><button v-for="c in filteredWires" :key="c.id" :class="{active:wire===c.id}" :aria-pressed="wire===c.id" @click="chooseWire(c.id)"><i :style="{background:c.color}"/><span><b>{{c.id}}</b> {{c.from.terminal}} → {{c.to.terminal}}<small>{{build.parts.find(p=>p.id===c.from.partId)?.name}} → {{build.parts.find(p=>p.id===c.to.partId)?.name}}</small></span></button></div>
            <p class="echo-wiring-safety">先断电再接线。线色仅是建议；按端子丝印核对，电机不能直接接 GPIO。电源支路按各条线路标注的线径。</p>
            <div class="echo-wire-downloads"><a :href="url('wiring.svg')" target="_blank">完整接线图 ↗</a><a :href="url('connections.csv')">下载连接表</a></div>
          </template>
          <template v-else><div class="echo-aside-heading">零件大纲 <span>{{build.parts.length}}</span></div><input class="echo-search" v-model="search" aria-label="搜索零件" placeholder="搜索打印件 / 电路板…"/><div class="echo-outliner"><div v-for="p in shownParts" :key="p.id" :class="{selected:selected.includes(p.id),hidden:hidden.includes(p.id)}"><button @click="selectPart(p,$event)"><i :style="{background:p.color}"/><span>{{p.name}}</span><small>{{p.kind==='printed'?'打印':'采购'}}</small></button><button :aria-label="(hidden.includes(p.id)?'显示 ':'隐藏 ')+p.name" @click="toggle(p.id)"><EyeOff v-if="hidden.includes(p.id)" :size="14"/><Eye v-else :size="14"/></button></div></div><section class="echo-inspector"><template v-if="current"><span>{{current.kind==='printed'?'PRINTED / PLA':'PURCHASED / REFERENCE'}}</span><h2>{{current.name}}</h2><h4>是什么 / 做什么</h4><p>{{current.explanation?.role}}</p><h4>为什么放在这里</h4><p>{{current.explanation?.whyHere}}</p><h4>设计与来源</h4><p>{{current.explanation?.whyThis}}</p><a v-if="String(current.source).startsWith('https://')" :href="current.source" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a></template><template v-else><Box :size="28"/><h2>看看里面的设计。</h2><p>点击模型或大纲中的任何零件，了解它是什么、为什么放在这里。隐藏外壳可看见内部。</p><button @click="hidden=[...coverIds]">打开外壳</button></template></section></template>
          <a class="echo-guide-link" :href="url('instructions.html')" target="_blank"><BookOpen :size="16"/>完整图文指南与固件安装<ChevronRight :size="16"/></a>
        </aside>
      </main><footer class="echo-status"><span><i/>本地制作包 · 无需模型服务</span><span>PLA · ESP32 · 相对响度控制 · 前进 / 停止</span><span>{{buildId==='echo-f1-cn-v2'?'CN V2':'V1'}} / 1:1 mm</span></footer>
    </template>
  </div>
</template>

<style scoped>
